mapper.select:
/* Tbm01Mapper.selectTbmEduInfo */ SELECT A.CMPNY_CD AS cmpnyCd , A.MTRL_CD AS mtrlCd , A.TITLE AS title , A.CONTENTS AS contents , A.MTRL_TYPE AS mtrlType , A.USE_YN AS useYn , COUNT(B.MTRL_ITEM_CD) AS mtrlCnt , A.SITE_CD AS siteCd /* 회사공통 여부: SITE_CD IS NULL 이면 'Y' */ , CASE WHEN A.SITE_CD IS NULL THEN 'Y' ELSE 'N' END AS isCommonContent /* 데이터 초기화용 값 */ , A.TITLE AS oriTitle , A.CONTENTS AS oriContents , A.MTRL_TYPE AS oriMtrlType , A.USE_YN AS oriUseYn
, FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER_NM', A.INSERT_NO, NULL) AS insertNm , DATE_FORMAT(A.INSERT_DATE, '%Y-%m-%d %H:%i') AS insertDate /* T5-2: 사용 중(취소 외 세션 참조) 여부. 'Y'면 수정/삭제 잠금 */ , ( SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END FROM TB_TBM_SESSION_CONTENT SC INNER JOIN TB_TBM_SESSION S ON (SC.CMPNY_CD = S.CMPNY_CD AND SC.SESSION_CD = S.SESSION_CD) WHERE SC.CMPNY_CD = A.CMPNY_CD AND SC.MTRL_CD = A.MTRL_CD AND S.DEL_YN = 'N' AND S.STATUS_CD != 'CANCELLED' ) AS lockedYn /* TBM_AI F1: 교육안 재열람(record 말미 순서 정합). GEN_CONTENT=text */ , A.GEN_CONTENT AS genContent , DATE_FORMAT(A.GEN_AT, '%Y-%m-%d %H:%i') AS genAt FROM TB_TBM_EDU_MTRL A
INNER JOIN TB_TBM_EDU_MTRL_ITEM B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.MTRL_CD = B.MTRL_CD AND B.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd} /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기사업장+회사공통 */
AND (A.SITE_CD IS NULL OR A.SITE_CD = #{scopeSiteCd})
/* 특정 사업장 필터(드롭다운 선택). 'COMMON' 은 회사공통만 */
AND A.SITE_CD IS NULL
AND A.SITE_CD = #{siteCd}
AND A.MTRL_CD = #{mtrlCd}
AND A.TITLE LIKE CONCAT('%', #{title}, '%')
AND A.MTRL_TYPE = #{mtrlType}
AND A.USE_YN = #{useYn}
GROUP BY A.CMPNY_CD , A.MTRL_CD , A.TITLE , A.CONTENTS , A.MTRL_TYPE , A.USE_YN , A.SITE_CD /* 회사공통(SITE_CD 없음) 자료를 항상 맨 위로. 그 다음은 자료코드(= 생성일 순). 기존에는 ORDER BY 자체가 없어 행 순서가 보장되지 않았다(MySQL 8 은 GROUP BY 암시 정렬 없음). */ ORDER BY (A.SITE_CD IS NULL OR A.SITE_CD = '') DESC , A.MTRL_CD

/* Tbm01Mapper.selectTbmEduItemInfo */ SELECT '' AS chk , A.MTRL_ITEM_CD AS mtrlItemCd , A.MTRL_CD AS mtrlCd , A.SORT_IDX AS sortIdx , A.MTRL_ITEM_TYPE AS mtrlItemType , A.MTRL_DESC AS mtrlDesc , A.FILE_MGMT_CD AS fileMgmtCd , B.FILE_NM AS fileNm , B.FILE_PATH AS filePath , B.FILE_EXT AS fileExt , A.URL AS url , A.USE_YN AS useYn , A.THUMB_FILE_MGMT_CD AS thumbFileMgmtCd , A.DURATION_SEC AS durationSec /* TBM_AI F1: 항목 AI 재열람(class 프로퍼티 매핑, 위치 무관) */ , A.AI_ANALYZE_YN AS aiAnalyzeYn , A.AI_STATUS AS aiStatus , A.AI_CONFIRM_DESC AS aiConfirmDesc /* 데이터 초기화 값 */ , A.SORT_IDX AS oriSortIdx , A.MTRL_ITEM_TYPE AS oriMtrlItemType , A.MTRL_DESC AS oriMtrlDesc , A.FILE_MGMT_CD AS oriFileMgmtCd , B.FILE_NM AS oriFileNm , B.FILE_PATH AS oriFilePath , B.FILE_EXT AS oriFileExt , A.URL AS oriUrl , A.USE_YN AS oriUseYn FROM TB_TBM_EDU_MTRL_ITEM A
INNER JOIN TB_TBM_EDU_MTRL M ON ( A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD ) LEFT OUTER JOIN TB_FILE_INFO B ON (
B.CMPNY_CD = A.CMPNY_CD AND A.FILE_MGMT_CD = B.FILE_MGMT_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.MTRL_CD = #{mtrlCd} ORDER BY A.SORT_IDX

    /* Tbm01Mapper.selectMtrlCd */
    SELECT CONCAT(DATE_FORMAT(CURDATE(), '%y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'MTRL_CD'))
	FROM DUAL

    /* Tbm01Mapper.selectMtrlItemCd */
    SELECT CONCAT(DATE_FORMAT(CURDATE(), '%y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'MTRL_ITEM_CD'))
	FROM DUAL

/* Tbm01Mapper.countOwnedMtrl */
SELECT COUNT(1)
FROM TB_TBM_EDU_MTRL
WHERE MTRL_CD = #{mtrlCd}
  AND CMPNY_CD = #{gvCmpnyCd}

mapper.update:
/* Tbm01Mapper.mergeTbmEduItemInfo */
INSERT INTO TB_TBM_EDU_MTRL_ITEM (
    MTRL_ITEM_CD
    /* 테넌트 격리: 항목 PK 는 (CMPNY_CD, MTRL_ITEM_CD) 복합키다. 회사코드는 항상 JWT 도출값(gvCmpnyCd). */
    , CMPNY_CD
    , MTRL_CD
    , SORT_IDX
    , MTRL_ITEM_TYPE
    , MTRL_DESC
    , FILE_MGMT_CD
    , THUMB_FILE_MGMT_CD
    , DURATION_SEC
    , URL
    , USE_YN
    , AI_ANALYZE_YN
    , AI_STATUS
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
) VALUES (
    #{mtrlItemCd}
    , #{gvCmpnyCd}
    , #{mtrlCd}
    /* SORT_IDX는 NOT NULL int. 빈문자/NULL 방어(미입력 시 DEFAULT 1) */
    , IFNULL(NULLIF(TRIM(#{sortIdx}), ''), 1)
    , #{mtrlItemType}
    , #{mtrlDesc}
    , #{fileMgmtCd}
    , #{thumbFileMgmtCd}
    , #{durationSec}
    , #{url}
    /* USE_YN NOT NULL. 미입력 시 'Y' 기본 */
    , IFNULL(NULLIF(TRIM(#{useYn}), ''), 'Y')
    /* TBM_AI v4: 항목별 AI 분석 지정. 신규/미전송 시 'N' 기본 */
    , IFNULL(NULLIF(TRIM(#{aiAnalyzeYn}), ''), 'N')
    /* AI_STATUS NULL 제거: 신규 INSERT 는 항상 'NONE'(미분석) 시작. 재큐잉/확정은 이후 EP·워커가 전이.
       ON DUPLICATE KEY UPDATE 의 AI_STATUS(=상태 보존/NONE 리셋)는 기존 로직 유지(NEW.AI_STATUS 미사용). */
    , 'NONE'
    , #{gvUserCd}
    , NOW()
    , #{gvUserCd}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    MTRL_ITEM_TYPE       = NEW.MTRL_ITEM_TYPE
    , MTRL_DESC          = NEW.MTRL_DESC
    , FILE_MGMT_CD       = NEW.FILE_MGMT_CD
    , THUMB_FILE_MGMT_CD = NEW.THUMB_FILE_MGMT_CD
    , DURATION_SEC       = NEW.DURATION_SEC
    , URL                = NEW.URL
    , USE_YN             = NEW.USE_YN
    , AI_ANALYZE_YN      = NEW.AI_ANALYZE_YN
    /* v4: 체크 해제(Y→N) 시 상태만 NONE 리셋(분석/확정 데이터 컬럼은 보존 → 통합 제외).
       체크 유지/재체크(=Y)면 기존 AI_STATUS 보존(재체크 항목은 analyze-items가 재큐잉). */
    /* ★기존 값 참조는 테이블명으로 한정한다. INSERT 컬럼 목록에 AI_STATUS 가 있어 행 별칭 NEW 에도
       동명 컬럼이 존재하므로, 한정자 없는 AI_STATUS 는 모호(MySQL Error 1052). */
    , AI_STATUS          = CASE WHEN NEW.AI_ANALYZE_YN = 'N' THEN 'NONE' ELSE TB_TBM_EDU_MTRL_ITEM.AI_STATUS END
    , UPDATE_NO          = NEW.UPDATE_NO
    , UPDATE_DATE        = NOW()

/* Tbm01Mapper.mergeTbmEduInfo */
INSERT INTO TB_TBM_EDU_MTRL (
    MTRL_CD,
    CMPNY_CD,
    SITE_CD,
    TITLE,
    CONTENTS,
    MTRL_TYPE,
    USE_YN,
    INSERT_NO,
    INSERT_DATE,
    UPDATE_NO,
    UPDATE_DATE
) VALUES (
    #{mtrlCd}
    , #{gvCmpnyCd}
    , #{siteCd}
    , #{title}
    , #{contents}
    , #{mtrlType}
    , #{useYn}
    , #{gvUserCd}
    , NOW()
    , #{gvUserCd}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    TITLE      		= NEW.TITLE
    , CONTENTS   	= NEW.CONTENTS
    , MTRL_TYPE  	= NEW.MTRL_TYPE
    , USE_YN     	= NEW.USE_YN
    /* 스코프(SITE_CD)는 수정 모드에서 변경 불가(FE-5). 전달값 NULL 이면 기존 값 보존.
       ★기존 값 참조는 테이블명으로 한정한다. 행 별칭 NEW 에도 SITE_CD 가 있어
       한정자 없는 SITE_CD 는 모호(MySQL Error 1052). */
    , SITE_CD    	= IFNULL(NEW.SITE_CD, TB_TBM_EDU_MTRL.SITE_CD)
    , UPDATE_NO   	= NEW.UPDATE_NO
    , UPDATE_DATE 	= NOW()

mapper.delete:
/* Tbm01Mapper.deleteTbmEduItemInfo */
/* 테넌트 격리(IDOR 방어): MTRL_ITEM_CD·MTRL_CD 는 모두 회사별 채번이라 전역 유일하지 않다.
   항목 자신의 CMPNY_CD 로 직접 좁혀야 타 회사 항목이 지워지지 않는다.
   (예전 주석의 "마스터 CMPNY_CD 불일치로 0행 삭제" 는 MTRL_CD 전역 유일 가정에 기댄 것이라 더는 성립하지 않는다.) */
DELETE I
FROM TB_TBM_EDU_MTRL_ITEM I
     INNER JOIN TB_TBM_EDU_MTRL M
        ON (I.CMPNY_CD = M.CMPNY_CD AND I.MTRL_CD = M.MTRL_CD)
WHERE I.CMPNY_CD = #{gvCmpnyCd}
  AND I.MTRL_ITEM_CD = #{mtrlItemCd}

/* Tbm01Mapper.deleteTbmEduInfo */
DELETE FROM TB_TBM_EDU_MTRL
WHERE MTRL_CD = #{mtrlCd}
  AND CMPNY_CD = #{gvCmpnyCd}

mapper.select:
/* Tbm01Mapper.selectTbmEduDetailItems */ SELECT '' AS chk , A.MTRL_ITEM_CD AS mtrlItemCd , A.MTRL_CD AS mtrlCd , A.SORT_IDX AS sortIdx , A.MTRL_ITEM_TYPE AS mtrlItemType , A.MTRL_DESC AS mtrlDesc , A.FILE_MGMT_CD AS fileMgmtCd , B.FILE_NM AS fileNm , B.FILE_PATH AS filePath , B.FILE_EXT AS fileExt , A.URL AS url , A.USE_YN AS useYn , A.THUMB_FILE_MGMT_CD AS thumbFileMgmtCd , A.DURATION_SEC AS durationSec /* TBM_AI F1: 항목 AI 재열람(미리보기 확정요지 노출용) */ , A.AI_ANALYZE_YN AS aiAnalyzeYn , A.AI_STATUS AS aiStatus , A.AI_CONFIRM_DESC AS aiConfirmDesc /* 데이터 초기화 값(상세 화면 미사용, class 프로퍼티 매핑) */ , A.SORT_IDX AS oriSortIdx , A.MTRL_ITEM_TYPE AS oriMtrlItemType , A.MTRL_DESC AS oriMtrlDesc , A.FILE_MGMT_CD AS oriFileMgmtCd , B.FILE_NM AS oriFileNm , B.FILE_PATH AS oriFilePath , B.FILE_EXT AS oriFileExt , A.URL AS oriUrl , A.USE_YN AS oriUseYn FROM TB_TBM_EDU_MTRL_ITEM A
INNER JOIN TB_TBM_EDU_MTRL M ON ( A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD ) LEFT OUTER JOIN TB_FILE_INFO B ON (
B.CMPNY_CD = A.CMPNY_CD AND A.FILE_MGMT_CD = B.FILE_MGMT_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.MTRL_CD = #{mtrlCd} AND A.USE_YN = 'Y' ORDER BY A.SORT_IDX

/* Tbm01Mapper.selectTbmEduLockingSessionCnt */
SELECT COUNT(1)
FROM TB_TBM_SESSION_CONTENT SC
	 INNER JOIN TB_TBM_SESSION S
	 	ON (SC.CMPNY_CD = S.CMPNY_CD AND SC.SESSION_CD = S.SESSION_CD)
WHERE SC.CMPNY_CD = #{gvCmpnyCd}
  AND SC.MTRL_CD = #{mtrlCd}
  AND S.DEL_YN = 'N'
  AND S.STATUS_CD != 'CANCELLED'

/* Tbm01Mapper.selectMtrlCdByItemCd */
/* 테넌트 격리: 항목 자신의 CMPNY_CD 로 좁힌다(MTRL_ITEM_CD 는 회사별 채번이라 전역 유일하지 않음). */
SELECT A.MTRL_CD
FROM TB_TBM_EDU_MTRL_ITEM A
	 INNER JOIN TB_TBM_EDU_MTRL M
	 	ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}
LIMIT 1

mapper.update:
/* Tbm01Mapper.updateTbmEduItemAiAnalyze */
UPDATE TB_TBM_EDU_MTRL_ITEM A
	 INNER JOIN TB_TBM_EDU_MTRL M
	 	ON (A.CMPNY_CD = M.CMPNY_CD AND A.MTRL_CD = M.MTRL_CD)
SET A.AI_ANALYZE_YN = #{aiAnalyzeYn}
  , A.AI_STATUS      = CASE WHEN #{aiAnalyzeYn} = 'N' THEN 'NONE' ELSE A.AI_STATUS END
  , A.UPDATE_NO      = #{gvUserCd}
  , A.UPDATE_DATE    = NOW()
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.MTRL_ITEM_CD = #{mtrlItemCd}
